INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('gargoyle-triax', 'Gargoyle', 'demon', 'rifts', 1, 'Typically anarchist or evil, but can be any.', '{"IQ":"2D6+2","ME":"3D6+1","MA":"2D6+2","PS":"2D6+18","PP":"2D6+18","PE":"2D6+18","PB":"2D6","Spd":"5D6"}', NULL, NULL, '1D6x100+100', '2D6', '1D4x10', 'Spd 5D6 is running; flying speed is 2D4x10+10. Hit Points and Natural Armor Rating both read ''See M.D.C.'': a mega-damage being on Rifts Earth, with no hit point or S.D.C. pool printed. P.P.E. 2D6 is for the typical gargoyle.', NULL, 16, '{"attacks":5,"initiative":2,"strike":1,"parry":2,"dodge":2}', 'In addition to physical attribute bonuses: +2 initiative, +1 strike, +2 parry and dodge, +4 dodge while in flight, +1 save vs psionic attacks, +10 save vs horror factor. Full strength claw/punch or kick rises to 4D6 M.D. with a P.S. of 31 or higher.', 'R.C.C. Warrior Skills: detect ambush (+10%), detect concealment (+10%), intelligence (+8%), track humanoids (+10%), wilderness survival (+15%), first aid (+5%), prowl (+10), climb (+10%), swim (-10%), W.P. sword, W.P. energy weapon of choice and two additional W.P. of choice (any); speaks Gargoyle, Dragonese/Elven and Gobblely 98% and can learn two other languages (+10%); six secondary skills from any category except electrical, mechanical, medical and science (no bonuses). The average NPC warrior is 1D4 level.', 'Winged flight; night sight that works on a tenth of the light a human needs and hawk-sharp daytime sight that picks out a foot-tall target at 2 miles; a strong, agile (not prehensile) tail usable as a striking limb; wing-assisted leaps of 100 feet (30.5 m); bio-regenerates 4D6 M.D. each hour.', 'None; only gargoyle mages can learn magic.', 'Meditation, mind block, presence sense, sense magic, telepathy, resist hunger, resist fatigue, resist thirst. Equal to a 6th level psychic.', '10 to 20 feet tall (3 to 6 m); wingspan 20 ft (6 m). The size chart gives a typical gargoyle an average of 15 feet.', '1200 to 2000 pounds (540 to 900 kg)', '300 to 500 years; some have lived as long as a thousand', 'Common in Europe and China, particularly Spain, France, Italy, Austria, Germany, Poland, Romania and Russia; favors mountains, forests and hills', 'Other supernatural beings and monstrous D-bees, especially trolls and other giants, mutant animals and lesser demons; the Splugorth. The Gargoyle Empire is officially allied with the New Phoenix Empire, Mindwerks, the brodkil and gene-splicers.', 'The New German Republic; vampires, ghouls and devilkins; most true supernatural beings', 'No O.C.C. choice: the ordinary gargoyle is a warrior using the R.C.C. warrior skill package, and a player character advances on the psi-stalker experience table. Lords, mages and gargoylites are separate R.C.C.s.', 'The Rifts Earth gargoyle: a winged, egg-hatched, warm-blooded mega-damage giant with green or grey-green hide and yellow eyes, a pack predator that swarms Europe in huge flocks and fights the NGR with heavy energy weapons. This is the M.D.C. version, not the Palladium Fantasy one.', 'Rifts World Book 5: Triax and the NGR p.197-199'),
('gurgoyle-triax', 'Gurgoyle', 'demon', 'rifts', 1, 'Typically anarchist or evil, but can be any.', '{"IQ":"2D6","ME":"3D6","MA":"2D6","PS":"2D6+24","PP":"2D6+18","PE":"2D6+18","PB":"2D6","Spd":"6D6+10"}', NULL, NULL, '1D4x100', '2D6', '1D4x10', 'Spd 6D6+10 is running; the gurgoyle is wingless and has no flying speed. Hit Points and Natural Armor Rating both read ''See M.D.C.'': a mega-damage being on Rifts Earth, with no hit point or S.D.C. pool printed. P.P.E. 2D6 is for the typical gurgoyle.', NULL, 14, '{"attacks":5,"initiative":2,"strike":1,"parry":2,"dodge":2}', 'In addition to physical attribute bonuses: +2 initiative, +1 strike, +2 parry and dodge, +1 save vs psionic attacks, +10 save vs horror factor. (The shared entry''s +4 dodge while in flight cannot apply to a wingless gurgoyle.) Full strength claw/punch or kick rises to 4D6 M.D. with a P.S. of 31 or higher.', 'R.C.C. Warrior Skills: detect ambush (+10%), detect concealment (+10%), escape artist (+10%, gurgoyles only), intelligence (+8%), track humanoids (+10%), wilderness survival (+15%), first aid (+5%), prowl (+10), climb (+10%), swim (+10%), W.P. sword, W.P. energy weapon of choice and two additional W.P. of choice (any); speaks Gargoyle, Dragonese/Elven and Gobblely 98% and can learn two other languages (+10%); six secondary skills from any category except electrical, mechanical, medical and science (no bonuses). The average NPC warrior is 1D4 level.', 'No wings and no flight. Night sight that works on a tenth of the light a human needs and hawk-sharp daytime sight that picks out a foot-tall target at 2 miles; a strong, agile (not prehensile) tail usable as a striking limb; leaps 40 feet (12 m); bio-regenerates 4D6 M.D. each hour.', 'None; only gargoyle mages can learn magic.', 'Meditation, mind block, presence sense, sense magic, telepathy, resist hunger, resist fatigue, resist thirst. Equal to a 6th level psychic.', '8 to 12 ft (2.4 to 3.6 m) tall', '800 to 1000 pounds (360 to 450 kg)', '300 to 500 years; some have lived as long as a thousand', 'Common in Europe and China, particularly Spain, France, Italy, Austria, Germany, Poland, Romania and Russia', 'Other supernatural beings and monstrous D-bees, especially trolls and other giants, mutant animals and lesser demons; the Splugorth. The Gargoyle Empire is officially allied with the New Phoenix Empire, Mindwerks, the brodkil and gene-splicers.', 'The New German Republic; vampires, ghouls and devilkins; most true supernatural beings', 'No O.C.C. choice: the ordinary gurgoyle is a warrior using the R.C.C. warrior skill package, and a player character advances on the psi-stalker experience table.', 'The Rifts Earth gurgoyle: a smaller, wingless cousin of the gargoyle and the foot soldier of the invading flocks. Gurgoyles are the ones who wear plate armor and crew the Gargoyle Empire''s power armor and giant robots, and they defer to gargoyles, lords and mages. This is the M.D.C. version, not the Palladium Fantasy one.', 'Rifts World Book 5: Triax and the NGR p.197-199'),
('gargoyle-lord-triax', 'Gargoyle Lord', 'demon', 'rifts', 1, 'Any, but usually anarchist or evil.', '{"IQ":"2D6+5","ME":"3D6+2","MA":"2D6+3","PS":"2D6+24","PP":"2D6+18","PE":"2D6+18","PB":"2D6+1","Spd":"5D6"}', NULL, NULL, '1D4x100+300', '6D6', '1D6x10', 'Spd 5D6 is running; flying speed is 2D4x10+10. Stone metamorphosis (three times per day, up to six hours each) adds 200 M.D.C. and 1D6 M.D. to punches and kicks, cuts speed by one-third and halves flying speed. Hit Points and Natural Armor Rating both read ''See M.D.C.''; no hit point or S.D.C. pool is printed.', NULL, 16, '{"attacks":6,"initiative":2,"strike":3,"parry":3,"dodge":3}', 'In addition to physical attribute bonuses: +2 initiative, +3 strike, parry and dodge, +6 dodge while in flight, +3 on all saving throws, +10 save vs horror factor.', 'R.C.C. Warlord Skills: detect ambush (+10%), detect concealment (+10%), intelligence (+12%), track humanoids (+15%), wilderness survival (+15%), land navigation (+10%), prowl (+5), climb (+10%), swim (-10%), W.P. sword, W.P. energy weapon of choice and three other W.P. of choice (any); speaks Gargoyle, Dragonese/Elven and Gobblely 98%, literate in Dragonese 88%, speaks four other languages (+10%); eight secondary skills from any category except electrical, mechanical, medical and science (+5%). NPC lords are 1D4+3 level, high lords 1D4+5 or higher, the Ultimate High Lord usually 10th or higher.', 'Turns to living stone three times a day for up to six hours a time (see the pools note), becomes invisible at will, teleports itself twice a day (2400 feet/732 m, 93% accuracy) and breathes fire once per melee, on top of every ordinary gargoyle ability: flight, superior night and day vision, wing-assisted leaps and regeneration.', 'None; only gargoyle mages can learn magic.', 'Meditation, mind block, presence sense, sense magic, telepathy, resist hunger, resist fatigue, resist thirst. Equal to a 6th level psychic.', '15 to 20 feet tall (4.6 to 6 m); the size chart shows a lord at 20 feet', 'Over two tons', 'Same as the basic gargoyle: 300 to 500 years, some as long as a thousand', 'Same as the basic gargoyle: Europe and China, favoring mountains, forests and hills', 'Same as the basic gargoyle; commands the gargoyles and gurgoyles of its flock', 'Same as the basic gargoyle', 'No O.C.C. choice: the lord is a warlord using its own R.C.C. skill package, and a player character advances on the dragon experience table.', 'The born ruler of the gargoyle race, about one gargoyle in a hundred: an elite warrior of royal standing who organizes flocks in war and migration, with stone-form, invisibility, teleport and fire breath that common gargoyles lack. Roughly one in four to eight thousand gargoyles is a high lord. This is the M.D.C. version, not the Palladium Fantasy one.', 'Rifts World Book 5: Triax and the NGR p.199-200'),
('gargoyle-mage-triax', 'Gargoyle Mage', 'demon', 'rifts', 1, 'Any, but usually anarchist or evil.', '{"IQ":"2D6+6","ME":"3D6+3","MA":"3D6","PS":"2D6+18","PP":"2D6+18","PE":"2D6+18","PB":"2D6","Spd":"5D6"}', NULL, NULL, '1D6x100+150', '3D6x10', '1D6x10', 'Spd 5D6 is running; flying speed is 2D4x10+10. P.P.E. is 3D6x10 plus 2D6 per level of experience. Hit Points and Natural Armor Rating both read ''See M.D.C.''; no hit point or S.D.C. pool is printed.', NULL, 16, '{"attacks":5,"initiative":3,"strike":2,"parry":2,"dodge":2}', 'Five physical attacks per melee or four magic attacks. In addition to physical attribute bonuses: +3 initiative, +2 strike, parry and dodge, +4 dodge while in flight, +4 save vs magic, +3 on all other saving throws, +12 save vs horror factor.', 'R.C.C. Skills: intelligence (+12%), track humanoids (+5%), wilderness survival (+10%), land navigation (+8%), streetwise (+10%), demon & monster lore (+20%), astronomy (+10%), basic and advanced math (+15%), first aid (+10%), prowl (+10%), climb (+10%), swim (-10%); speaks Dragonese/Elven and Gobblely 98%, literate in Dragonese 98% and two others (+20%), speaks four other languages (+20%); twelve secondary skills from any category (+10% on all). The average NPC mage is 1D4+1 level, an experienced one 2D4+2.', 'Becomes invisible at will for as long as it likes, teleports itself twice per 24 hours (2400 feet/732 m, 93% accuracy), breathes fire once per melee and works earth elemental magic, on top of every ordinary gargoyle ability: flight, superior night and day vision, wing-assisted leaps and regeneration. Unlike the lord it has no stone form.', 'All level 1-3 earth elemental magic spells, cast as a fourth level warlock. Speaks to all elemental beings (80%), has an 80% chance to see even an invisible elemental, and senses elementals within 1000 feet (305 m). May study other magic, herbology included, though few do. The book points to Rifts Conversion Book One for the Warlock O.C.C. and elemental magic.', 'Meditation, mind block, presence sense, sense magic, sense evil, detect psionics, healing touch, exorcism, telepathy, resist hunger, resist fatigue, resist thirst. Equal to a 6th level psychic.', '15 to 20 feet tall (4.6 to 6 m)', NULL, 'Same as the gargoyle: 300 to 500 years, some as long as a thousand', 'Same as the gargoyle; some leave the flock to rule small kingdoms of non-gargoyles', 'Same as the gargoyle; often keeps 2D4 gargoyles and 3D4 gurgoyles as a personal guard, and favors gargoylites as minions', 'Same as the gargoyle', 'The entry lists its R.C.C.s as warlock and scholar; there is no other O.C.C. choice, and a player character advances on the dragon experience table.', 'A rare gargoyle, about one in twenty thousand, born with a link to elemental earth magic. Outwardly an ordinary gargoyle, it is usually the cleverest and most persuasive member of the clan and tends to rule from behind a lord''s throne, or to set itself up as a god-king over goblins, kobolds and orcs. This is the M.D.C. version, not the Palladium Fantasy one.', 'Rifts World Book 5: Triax and the NGR p.200-201'),
('gargoylite-triax', 'Gargoylite', 'demon', 'rifts', 1, 'Typically anarchist, but can be any.', '{"IQ":"2D6+2","ME":"3D6+1","MA":"3D6+2","PS":"1D6+18","PP":"1D6+16","PE":"2D6+16","PB":"2D6","Spd":"3D6"}', NULL, NULL, '1D4x100', '4D6', '6D6', 'Spd 3D6 is running; flying speed is 1D4x10+10. Stone metamorphosis (three times per day, up to six hours each) adds 100 M.D.C. and 1D6 M.D. to punches and kicks, cuts speed by one-third and halves flying speed. No hit point or S.D.C. pool is printed.', NULL, 10, '{"attacks":4,"initiative":2,"strike":1,"parry":2,"dodge":2}', 'In addition to physical attributes: +2 initiative, +1 strike, +2 parry and dodge, +4 dodge while in flight, +3 on all saving throws, +10 save vs horror factor.', 'R.C.C. Spy-Thief Skills: escape artist (+10%), intelligence (+10%), wilderness survival (+10%), land navigation (+10%), pick locks (+10%), pick pockets (+5%), palming (+10%), concealment (+5%), prowl (+10), climb (+10%), swim (-10%), W.P. knife, W.P. energy pistol, basic math (+15%); speaks Dragonese/Elven and Gobblely 98% and two other languages (+10%); six secondary skills from any category except electrical, mechanical, medical and science (no bonuses). The average NPC is 1D4+1 level.', 'Turns to living stone three times a day for up to six hours a time (see the pools note); flies on stubby wings that still lift it plus 500 pounds, though for no more than 30 minutes at a stretch; nightvision 120 ft (36.6 m) even in total darkness, hawk-sharp sight by day and owl-like sight by night; wing-assisted leaps of 20 feet (6 m); bio-regenerates 6D6 M.D.C. each hour; becomes invisible at will; breathes fire once per melee. Its short tail is useless in a fight.', 'None, other than natural abilities.', 'Meditation, mind block, presence sense, sense magic, see aura, object read, telepathy, resist hunger, resist fatigue, resist thirst. Equal to a 4th level psychic.', 'Three feet tall (0.9 m)', '100 pounds (45 kg)', '400 to 600 years; some have lived over a thousand', 'Same as gargoyles', 'Gargoyle lords and mages, who use them as spies; shifters, summoners and other powerful beings', NULL, 'No O.C.C. choice: the ordinary gargoylite is a spy, thief and scavenger using its own R.C.C. skill package, and a player character advances on the Dog Pack experience table.', 'A squat, pot-bellied, three-foot relative of the gargoyle lord with green skin, tiny horns and yellow-orange eyes. It has little appetite for battle or rule but an obsessive greed for gemstones, and its knack for sneaking and trickery makes it the preferred spy of lords and mages. This is the M.D.C. version, not the Palladium Fantasy one.', 'Rifts World Book 5: Triax and the NGR p.201-202');
