-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 5 creatures are in' AS assertion, count(*) AS got, 5 AS want
  FROM creatures WHERE slug IN ('gargoyle-triax', 'gurgoyle-triax', 'gargoyle-lord-triax', 'gargoyle-mage-triax', 'gargoylite-triax');
SELECT 'and 5 of them are playable' AS assertion, count(*) AS got, 5 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('gargoyle-triax', 'gurgoyle-triax', 'gargoyle-lord-triax', 'gargoyle-mage-triax', 'gargoylite-triax');
SELECT 'the creatures carry 30 attacks' AS assertion, count(*) AS got, 30 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('gargoyle-triax', 'gurgoyle-triax', 'gargoyle-lord-triax', 'gargoyle-mage-triax', 'gargoylite-triax');

